);

/** Eine Aktivität: global definiert, jeden Tag separat abhakbar. */
export interface Activity {
  id: string;
  /** Anzeigename, Pflichtfeld. */
  name: string;
  /** Optionale Beschreibung; leerer String = keine. */
  description: string;
  /** Kategorie als Freitext; leere Eingabe wird als "Ohne Kategorie" gespeichert. */
  category: string;
  /**
   * Tagesziel als ganze Zahl ≥ 1.
   * 1 = einmal abhaken; > 1 = pro Klick zählen, fertig bei Erreichen des Ziels.
   */
  target: number;
  /** ISO-Zeitstempel der Anlage. */
  createdAt: string;
}

/** Kalenderdatum als lokale Zeit, Format `YYYY-MM-DD`. */
export type DayKey = string;

/** Zählstand pro Aktivität für einen Tag: activityId → Anzahl (0..target). */
export type DayProgress = Record<string, number>;

/**
 * Versioniertes Gesamtdokument, das in localStorage abgelegt wird.
 * `version` steigt bei Strukturwechseln; `storage.ts` migriert alte Versionen.
 */
export interface AppData {
  version: number;
  activities: Activity[];
  /** Tagesstatus strikt nach Datum getrennt – Tage überschreiben sich nie. */
  progress: Record<DayKey, DayProgress>;
}

/** Wie der gespeicherte Zustand beim Laden eingestuft wurde. */
export type Recovery = 'ok' | 'migrated' | 'corrupt' | 'empty';

import type { DayKey } from './types';

const KEY_RE = /^(\d{4})-(\d{2})-(\d{2})$/;

/** `Date` → lokaler DayKey (`YYYY-MM-DD`). */
export function toKey(date: Date): DayKey {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}

/** DayKey für "heute" (lokale Zeit). */
export function todayKey(now: Date = new Date()): DayKey {
  return toKey(now);
}

/** DayKey → `Date` auf 0:00 Uhr lokaler Zeit; ungültige Keys liefern `null`. */
export function fromKey(key: DayKey): Date | null {
  const m = KEY_RE.exec(key);
  if (!m) return null;
  const date = new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
  return Number.isNaN(date.getTime()) ? null : date;
}

/** Strikt prüfen, ob der String ein gültiger lokaler Kalendertag ist. */
export function isValidKey(key: string): boolean {
  const date = fromKey(key);
  if (!date) return false;
  // fromKey normalisiert (z. B. 2026-02-31 → 3. März), deshalb rückprüfen.
  return toKey(date) === key;
}

/** DayKey um `delta` Tage verschieben (negativ erlaubt). */
export function addDays(key: DayKey, delta: number): DayKey {
  const date = fromKey(key) ?? new Date();
  const shifted = new Date(date);
  shifted.setDate(shifted.getDate() + delta);
  return toKey(shifted);
}

/** Ist der Tag streng in der Zukunft (relativ zu `now`)? */
export function isFuture(key: DayKey, now: Date = new Date()): boolean {
  return key > todayKey(now);
}

/** Ist der Tag der heutige? */
export function isToday(key: DayKey, now: Date = new Date()): boolean {
  return key === todayKey(now);
}

/** "Donnerstag, 27. September" – lange Form für den Kopfbereich. */
export function formatLong(key: DayKey): string {
  const date = fromKey(key);
  if (!date) return key;
  return new Intl.DateTimeFormat('de-DE', {
    weekday: 'long',
    day: 'numeric',
    month: 'long',
  }).format(date);
}

/** "27. Sep." – kurze Form (z. B. für den „Heute“-Kontext). */
export function formatShort(key: DayKey): string {
  const date = fromKey(key);
  if (!date) return key;
  return new Intl.DateTimeFormat('de-DE', {
    day: 'numeric',
    month: 'short',
  }).format(date);
}

import type { Activity, AppData, DayProgress, Recovery } from './types';
import { isValidKey } from './dates';

/** localStorage-Schlüssel für das Gesamtdokument. */
export const STORAGE_KEY = 'pulseboard:data';

/** Aktuelle Schema-Version; ältere Versionen werden von `migrate()` übernommen. */
export const SCHEMA_VERSION = 1;

const FALLBACK_CATEGORY = 'Ohne Kategorie';

/* ---------- kleine, strikte Typ-Wächter ---------- */

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isString(value: unknown): value is string {
  return typeof value === 'string';
}

function isNumber(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value);
}

/** Positive ganze Zahl; `null` bei nichts Sinnvollem. */
function asPositiveInt(value: unknown, fallback: number): number {
  if (typeof value === 'number' && Number.isInteger(value) && value > 0) return value;
  if (typeof value === 'string' && /^\d+$/.test(value) && Number(value) > 0) {
    return Number(value);
  }
  return fallback;
}

/**
 * Zählstand auf das sinnvolle Maß begrenzen.
 * `null` = Eintrag verwerfen (z. B. negative Zahl, NaN, kein Bezug mehr zur Aktivität).
 */
function asCount(value: unknown, target: number): number | null {
  if (!isNumber(value) && !(typeof value === 'string' && value !== '' && Number.isInteger(Number(value)))) {
    return null;
  }
  const n = Math.trunc(Number(value));
  if (Number.isNaN(n) || n < 0) return null;
  return Math.min(n, Math.max(target, 1));
}

/* ---------- Migration & Validierung ---------- */

/**
 * Migration alter Dokumente. Aktuell ist v1 die Anfangsversion, daher ist der
 * Durchlauf eine Identity – die Struktur ist aber vorbereitet, damit ein
 * Versionsbump (z. B. v1 → v2) nur eine Funktion hier ergänzt.
 */
export function migrate(raw: AppData): AppData {
  return { ...raw };
}

function sanitizeActivity(value: unknown, seenIds: Set<string>): Activity | null {
  if (!isRecord(value)) return null;
  const id = isString(value.id) && value.id !== '' ? value.id : null;
  if (!id || seenIds.has(id)) return null;
  const name = isString(value.name) ? value.name.trim() : '';
  if (name === '') return null; // ohne Namen nicht benutzbar → Eintrag fällt raus
  seenIds.add(id);

  return {
    id,
    name,
    description: isString(value.description) ? value.description.slice(0, 500) : '',
    category:
      isString(value.category) && value.category.trim() !== ''
        ? value.category.trim().slice(0, 60)
        : FALLBACK_CATEGORY,
    target: asPositiveInt(value.target, 1),
    createdAt: isString(value.createdAt) ? value.createdAt : '',
  };
}

function sanitizeDayProgress(value: unknown, activities: Map<string, Activity>): DayProgress | null {
  if (!isRecord(value)) return null;
  const out: DayProgress = {};
  for (const [activityId, rawCount] of Object.entries(value)) {
    const activity = activities.get(activityId);
    if (!activity) continue; // Referenz zu gelöschter/unbekannter Aktivität → verwerfen
    const count = asCount(rawCount, activity.target);
    if (count === null) continue;
    out[activityId] = count;
  }
  return out;
}

/**
 * Speichertes, beliebtes `unknown` in ein sicheres `AppData` verwandeln.
 *
 * - `null` → das Dokument ist nicht zu retten (unerwartete Struktur, kaputtes JSON,
 *   falsche Wurzeltypen). Die App startet leer und zeigt das an.
 * - sonst → best-effort gerettetes, normalisiertes Dokument; ungültige Einträge
 *   fallen raus, statt die App zu crashen.
 */
export function parseStored(raw: unknown): { data: AppData | null; migrated: boolean } {
  if (!isRecord(raw) || !isNumber(raw.version)) {
    return { data: null, migrated: false };
  }
  const before = Math.floor(raw.version as number);
  const migrated = before < SCHEMA_VERSION;

  const activities: Activity[] = [];
  const seenIds = new Set<string>();
  if (Array.isArray(raw.activities)) {
    for (const entry of raw.activities) {
      const activity = sanitizeActivity(entry, seenIds);
      if (activity) activities.push(activity);
    }
  }

  const activityMap = new Map(activities.map((a) => [a.id, a]));
  const progress: Record<string, DayProgress> = {};
  if (isRecord(raw.progress)) {
    for (const [day, rawDay] of Object.entries(raw.progress)) {
      if (!isValidKey(day)) continue; // fremde/ungültige Datums-Keys weg
      const dayProgress = sanitizeDayProgress(rawDay, activityMap);
      if (dayProgress && Object.keys(dayProgress).length > 0) progress[day] = dayProgress;
    }
  }

  const data: AppData = {
    version: SCHEMA_VERSION,
    activities,
    progress,
  };
  return { data: migrate(data), migrated };
}

/* ---------- Zugriff auf localStorage ---------- */

function readRaw(): string | null {
  try {
    return window.localStorage.getItem(STORAGE_KEY);
  } catch {
    // Speicher unzugänglich (z. B. privater Modus mit deaktiviertem Storage) → leer.
    return null;
  }
}

/**
 * Gespeichertes Dokument laden. Crasht bei kaputten oder veralteten Daten nie:
 * - nichts gespeichert        → leeres Dokument, Recovery "empty"
 * - nicht lesbares JSON        → Recovery "corrupt"
 * - alte Version              → Daten + Recovery "migrated"
 * - sonst                     → Daten + Recovery "ok"
 */
export function load(): { data: AppData; recovery: Recovery } {
  const rawText = readRaw();
  if (rawText === null) {
    return { data: emptyData(), recovery: 'empty' };
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(rawText);
  } catch {
    return { data: emptyData(), recovery: 'corrupt' };
  }
  const { data, migrated } = parseStored(parsed);
  if (data === null) {
    return { data: emptyData(), recovery: 'corrupt' };
  }
  return {
    data,
    recovery: migrated ? 'migrated' : 'ok',
  };
}

/** Neues, leeres Dokument. */
export function emptyData(): AppData {
  return { version: SCHEMA_VERSION, activities: [], progress: {} };
}

/**
 * Dokument persistieren. Gibt `false`, wenn der Schreibzugriff fehlgeschlagen ist
 * (z. B. Speicher voll) – die App zeigt dann eine Meldung, statt zu crashen.
 */
export function save(data: AppData): boolean {
  try {
    window.localStorage.setItem(
      STORAGE_KEY,
      JSON.stringify({ ...data, version: SCHEMA_VERSION }),
    );
    return true;
  } catch {
    return false;
  }
}

import type { Activity, AppData, DayKey, DayProgress } from '../lib/types';
import { isFuture } from '../lib/dates';
import { emptyData } from '../lib/storage';

/** Eingehende Aktionen des Stores. */
export type Action =
  | { type: 'activity/add'; activity: Omit<Activity, 'id' | 'createdAt'> }
  | {
      type: 'activity/update';
      id: string;
      patch: Pick<Activity, 'name' | 'description' | 'category' | 'target'>;
    }
  | { type: 'activity/delete'; id: string }
  | { type: 'progress/toggle'; date: DayKey; id: string }
  | { type: 'progress/decrement'; date: DayKey; id: string }
  /** Kompletter Datenersatz (z. B. Reset nach nicht lesbaren gespeicherten Daten). */
  | { type: 'data/replace'; data: AppData };

export function createId(): string {
  if (typeof crypto !== 'undefined' && 'randomUUID' in crypto) return crypto.randomUUID();
  return `act-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
}

/**
 * Zählstand für eine Aktivität am Tag, immer 0..target.
 * Fehlt die Aktivität (gelöscht) oder der Tag → 0.
 */
export function countFor(
  data: AppData,
  date: DayKey,
  activity: Pick<Activity, 'id' | 'target'>,
): number {
  const raw = data.progress[date]?.[activity.id] ?? 0;
  if (!Number.isFinite(raw) || raw < 0) return 0;
  return Math.min(raw, Math.max(activity.target, 1));
}

/** Erledigt = Zählstand erreicht das Tagesziel. */
export function isDone(
  data: AppData,
  date: DayKey,
  activity: Pick<Activity, 'id' | 'target'>,
): boolean {
  return countFor(data, date, activity) >= Math.max(activity.target, 1);
}

function dayEntry(data: AppData, date: DayKey): { day: DayProgress; changed: boolean } {
  return { day: data.progress[date] ?? {}, changed: false };
}

/**
 * Reducer. Bewusst pure und strikt:
 * - Toggle nur für nicht-künftige Tage (zweite Verteidigung neben der UI).
 * - Zähl-Semantik: volle Menge erreicht → zurück auf 0, sonst +1 (max. target).
 * - Deleted Aktivitäten werden aus allen Tageseinträgen bereinigt.
 */
export function reducer(state: AppData, action: Action): AppData {
  switch (action.type) {
    case 'activity/add': {
      const activity: Activity = {
        id: createId(),
        createdAt: new Date().toISOString(),
        ...action.activity,
      };
      return { ...state, activities: [...state.activities, activity] };
    }

    case 'activity/update': {
      return {
        ...state,
        activities: state.activities.map((a) =>
          a.id === action.id ? { ...a, ...action.patch } : a,
        ),
      };
    }

    case 'activity/delete': {
      const progress: AppData['progress'] = {};
      for (const [day, dayProgress] of Object.entries(state.progress)) {
        if (!(action.id in dayProgress)) {
          progress[day] = dayProgress;
          continue;
        }
        const copy: DayProgress = { ...dayProgress };
        delete copy[action.id];
        if (Object.keys(copy).length > 0) progress[day] = copy;
      }
      return {
        ...state,
        activities: state.activities.filter((a) => a.id !== action.id),
        progress,
      };
    }

    case 'progress/toggle': {
      if (isFuture(action.date)) return state;
      const activity = state.activities.find((a) => a.id === action.id);
      if (!activity) return state;
      const { day } = dayEntry(state, action.date);
      const current = countFor(state, action.date, activity);
      const target = Math.max(activity.target, 1);
      const next = current >= target ? 0 : current + 1;
      const dayProgress: DayProgress = { ...day, [action.id]: next };
      if (next === 0) delete dayProgress[action.id];
      return { ...state, progress: { ...state.progress, [action.date]: dayProgress } };
    }

    case 'progress/decrement': {
      if (isFuture(action.date)) return state;
      const activity = state.activities.find((a) => a.id === action.id);
      if (!activity) return state;
      const { day } = dayEntry(state, action.date);
      const current = countFor(state, action.date, activity);
      if (current <= 0) return state;
      const next = current - 1;
      const dayProgress: DayProgress = { ...day };
      if (next === 0) delete dayProgress[action.id];
      else dayProgress[action.id] = next;
      return { ...state, progress: { ...state.progress, [action.date]: dayProgress } };
    }

    case 'data/replace':
      return action.data;

    default:
      return state;
  }
}

/* ---------- Selectoren (pure, getestete Funktionen) ---------- */

export interface DayStats {
  total: number;
  done: number;
  open: number;
  /** 0..100, gerundet; 0 ohne Aktivitäten. */
  percent: number;
}

export function statsForDay(data: AppData, date: DayKey): DayStats {
  const total = data.activities.length;
  const done = data.activities.filter((a) => isDone(data, date, a)).length;
  const open = total - done;
  const percent = total === 0 ? 0 : Math.round((done / total) * 100);
  return { total, done, open, percent };
}

export interface CategoryStat {
  category: string;
  total: number;
  done: number;
}

/** Übersicht nach Kategorie, alphabetisch sortiert (ruhig, vorhersagbar). */
export function categoryStats(data: AppData, date: DayKey): CategoryStat[] {
  const byCategory = new Map<string, CategoryStat>();
  for (const activity of data.activities) {
    const entry =
      byCategory.get(activity.category) ?? { category: activity.category, total: 0, done: 0 };
    entry.total += 1;
    if (isDone(data, date, activity)) entry.done += 1;
    byCategory.set(activity.category, entry);
  }
  return [...byCategory.values()].sort((a, b) => a.category.localeCompare(b.category, 'de'));
}

/** Leere Umsatzzähler für Tests/Reset. */
export function freshData(): AppData {
  return emptyData();
}

