import {
  createContext,
  useContext,
  useEffect,
  useMemo,
  useReducer,
  useRef,
  type ReactNode,
} from 'react';
import type { AppData, Recovery } from '../lib/types';
import { load, save } from '../lib/storage';
import { reducer, type Action } from './store';
import { ToastProvider } from './Toasts';

interface AppState {
  data: AppData;
  recovery: Recovery;
}

interface AppContextValue {
  data: AppData;
  recovery: Recovery;
  dispatch: (action: Action) => void;
  /** Die corrupt-Meldung einmalig wegklicken. */
  dismissRecovery: () => void;
}

const AppContext = createContext<AppContextValue | null>(null);

function init(): AppState {
  const { data, recovery } = load();
  return { data, recovery };
}

/**
 * Hält das AppData im Reducer, lädt einmalig aus localStorage und speichert bei
 * jeder Änderung zurück. Bei nicht lesbaren Daten wird nicht sofort überschrieben
 * (der kaputte Zustand bleibt sichtbar, bis der Nutzer wirklich etwas ändert).
 */
export function AppProvider({ children }: { children: ReactNode }) {
  const [state, dispatch] = useReducer(reducer, undefined, init);
  const [recoveryDismissed, setRecoveryDismissed] = useStateFlag();

  const { pushToast } = useToast();
  const recovery = state.recovery;

  const firstRun = useRef(true);
  const wasCorrupt = useRef(state.recovery === 'corrupt');

  useEffect(() => {
    if (firstRun.current) {
      firstRun.current = false;
      if (wasCorrupt.current) {
        // Nicht lesbare Daten: erst beim ersten echten Nutzeränderung überschreiben.
        return;
      }
    }
    if (!save(state.data)) {
      pushToast('Änderung konnte nicht gespeichert werden – Speicher似乎是 voll oder gesperrt.');
    }
  }, [state.data, pushToast]);

  // Recovery-Status zurücksetzen, sobald neue Daten erfolgreich persistiert sind.
  useEffect(() => {
    if (wasCorrupt.current && !firstRun.current) {
      wasCorrupt.current = false;
      setRecoveryDismissed(true);
    }
  }, [state.data, setRecoveryDismissed]);

  const value = useMemo<AppContextValue>(
    () => ({
      data: state.data,
      recovery: recoveryDismissed ? 'ok' : recovery,
      dispatch,
      dismissRecovery: () => setRecoveryDismissed(true),
    }),
    [state.data, recovery, recoveryDismissed, setRecoveryDismissed],
  );

  return (
    <ToastProvider>
      <AppContext.Provider value={value}>{children}</AppContext.Provider>
    </ToastProvider>
  );
}

/** Kleiner Hilfe-Hook: separates „dismissed“-Flag über useState. */
function useStateFlag(): [boolean, (v: boolean) => void] {
  const [value, setValue] = useBooleanState();
  return [value, setValue];
}

import { useState as useBooleanState } from 'react';

export function useApp(): AppContextValue {
  const ctx = useContext(AppContext);
  if (!ctx) throw new Error('useApp muss innerhalb von <AppProvider> verwendet werden');
  return ctx;
}

export function useToast() {
  return useContext(ToastContextRef);
}

// ── Toast-Context (separate Datei, hier nur der Referenz-Pass-through) ──
import { ToastContextRef } from './Toasts';

import {
  createContext,
  useCallback,
  useContext,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react';

export type ToastTone = 'info' | 'error';

interface ToastItem {
  id: number;
  message: string;
  tone: ToastTone;
}

interface ToastContextValue {
  pushToast: (message: string, tone?: ToastTone) => void;
  toasts: ToastItem[];
  dismissToast: (id: number) => void;
}

const ToastContext = createContext<ToastContextValue | null>(null);

const TOAST_TTL_MS = 6000;

export function ToastProvider({ children }: { children: ReactNode }) {
  const [toasts, setToasts] = useState<ToastItem[]>([]);
  const nextId = useRef(1);

  const dismissToast = useCallback((id: number) => {
    setToasts((current) => current.filter((t) => t.id !== id));
  }, []);

  const pushToast = useCallback(
    (message: string, tone: ToastTone = 'info') => {
      const id = nextId.current++;
      setToasts((current) => [...current.slice(-2), { id, message, tone }]);
      window.setTimeout(() => dismissToast(id), TOAST_TTL_MS);
    },
    [dismissToast],
  );

  const value = useMemo(
    () => ({ pushToast, toasts, dismissToast }),
    [pushToast, toasts, dismissToast],
  );

  return <ToastContext.Provider value={value}>{children}</ToastContext.Provider>;
}

export function useToast(): ToastContextValue {
  const ctx = useContext(ToastContext);
  if (!ctx) throw new Error('useToast muss innerhalb von <ToastProvider> verwendet werden');
  return ctx;
}

/** Screenreader-sichtbare, sichtbare Toast-Leiste. */
export function ToastViewport() {
  const { toasts, dismissToast } = useToast();
  return (
    <div className="toasts" role="status" aria-live="polite">
      {toasts.map((toast) => (
        <div key={toast.id} className={`toast toast--${toast.tone}`}>
          <span className="toast__message">{toast.message}</span>
          <button
            type="button"
            className="toast__close"
            onClick={() => dismissToast(toast.id)}
            aria-label="Meldung schließen"
          >
            ✕
          </button>
        </div>
      ))}
    </div>
  );
}

import {
  createContext,
  useContext,
  useEffect,
  useMemo,
  useReducer,
  useRef,
  useState,
  type ReactNode,
} from 'react';
import type { AppData, Recovery } from '../lib/types';
import { load, save } from '../lib/storage';
import { reducer, type Action } from './store';
import { ToastProvider, useToast } from './Toasts';

interface AppState {
  data: AppData;
  recovery: Recovery;
}

interface AppContextValue {
  data: AppData;
  /** Wie der gespeicherte Zustand beim Laden eingestuft wurde (nach dem Ausblenden: "ok"). */
  recovery: Recovery;
  dispatch: (action: Action) => void;
  dismissRecovery: () => void;
}

const AppContext = createContext<AppContextValue | null>(null);

function init(): AppState {
  const { data, recovery } = load();
  return { data, recovery };
}

/**
 * Hält das AppData im Reducer, lädt einmalig aus localStorage und speichert bei
 * jeder Änderung zurück.
 *
 * Sonderfall „corrupt“: Nicht lesbare Daten werden beim ersten Rendern nicht
 * sofort überschrieben – der kaputte Zustand bleibt bestehen, bis der Nutzer
 * tatsächlich etwas ändert (damit das Banner bei jedem Reload ehrlich bleibt).
 */
export function AppProvider({ children }: { children: ReactNode }) {
  const [state, dispatch] = useReducer(reducer, undefined, init);
  const [corruptHandled, setCorruptHandled] = useState(false);
  const { pushToast } = useToast();

  const firstRun = useRef(true);
  const startedCorrupt = useRef(state.recovery === 'corrupt');

  useEffect(() => {
    if (firstRun.current) {
      firstRun.current = false;
      if (startedCorrupt.current) return; // erst nach echten Änderungen überschreiben
    }
    if (!save(state.data)) {
      pushToast('Änderung konnte nicht gespeichert werden – der Browser-Speicher ist voll oder gesperrt.');
    }
  }, [state.data, pushToast]);

  useEffect(() => {
    if (startedCorrupt.current && !firstRun.current) {
      // Erste echte Änderung persistiert → kaputter Zustand wurde ersetzt.
      startedCorrupt.current = false;
      setCorruptHandled(true);
    }
  }, [state.data]);

  const value = useMemo<AppContextValue>(
    () => ({
      data: state.data,
      recovery: corruptHandled ? 'ok' : state.recovery,
      dispatch,
      dismissRecovery: () => setCorruptHandled(true),
    }),
    [state.data, state.recovery, corruptHandled],
  );

  return (
    <ToastProvider>
      <AppContext.Provider value={value}>{children}</AppContext.Provider>
    </ToastProvider>
  );
}

export function useApp(): AppContextValue {
  const ctx = useContext(AppContext);
  if (!ctx) throw new Error('useApp muss innerhalb von <AppProvider> verwendet werden');
  return ctx;
}

import { useCallback, useEffect, useState } from 'react';
import type { DayKey } from '../lib/types';
import { isValidKey, todayKey } from '../lib/dates';

const HASH_RE = /^#\/(\d{4}-\d{2}-\d{2})$/;

/**
 * Gelesen aus der URL-Hash: `#/2026-09-27` → Tag, sonst (leere/ungültige Hash) → heute.
 * Die Hash ist die einzige Wahrheit für den angezeigten Tag, dadurch bleibt der
 * Tag über Reloads erhalten und Browser-Back/Forward funktioniert.
 */
export function dayFromHash(): DayKey {
  const match = HASH_RE.exec(window.location.hash);
  if (match && isValidKey(match[1])) return match[1];
  return todayKey();
}

/**
 * Angezeigter Tag + Auswahl. `selectDay` schreibt in die Hash und löst
 * `hashchange` aus, worauf der State synchronisiert wird.
 */
export function useSelectedDay(): [DayKey, (day: DayKey) => void] {
  const [day, setDay] = useState<DayKey>(dayFromHash);

  useEffect(() => {
    const onHashChange = () => setDay(dayFromHash());
    window.addEventListener('hashchange', onHashChange);
    return () => window.removeEventListener('hashchange', onHashChange);
  }, []);

  const selectDay = useCallback((next: DayKey) => {
    const hash = `/${next}`;
    if (window.location.hash === hash) {
      // Gleicher Tag: Event würdes nicht ausgelöst → State direkt setzen.
      setDay(next);
      return;
    }
    window.location.hash = hash;
  }, []);

  return [day, selectDay];
}

