import type { SVGProps } from 'react';

type IconProps = SVGProps<SVGSVGElement> & { size?: number };

function base(size: number, props: IconProps) {
  const { size: _size, ...rest } = props;
  return {
    width: size,
    height: size,
    viewBox: '0 0 16 16',
    fill: 'none',
    stroke: 'currentColor',
    strokeWidth: 1.6,
    strokeLinecap: 'round' as const,
    strokeLinejoin: 'round' as const,
    'aria-hidden': true,
    ...rest,
  };
}

export function IconCheck(props: IconProps) {
  return (
    <svg {...base(props.size ?? 14, props)}>
      <path d="M3 8.5 6.2 11.5 13 4.5" />
    </svg>
  );
}

export function IconPencil(props: IconProps) {
  return (
    <svg {...base(props.size ?? 15, props)}>
      <path d="M11.3 2.7a1.7 1.7 0 0 1 2.4 2.4L5 13.8l-3.2.9.9-3.2 8.6-8.8Z" />
    </svg>
  );
}

export function IconTrash(props: IconProps) {
  return (
    <svg {...base(props.size ?? 15, props)}>
      <path d="M2.5 4.5h11M6.5 2.5h3M4.5 4.5 5.3 13h5.4l.8-8.5M6.7 7v4M9.3 7v4" />
    </svg>
  );
}

export function IconPlus(props: IconProps) {
  return (
    <svg {...base(props.size ?? 15, props)}>
      <path d="M8 3v10M3 8h10" />
    </svg>
  );
}

export function IconChevronLeft(props: IconProps) {
  return (
    <svg {...base(props.size ?? 16, props)}>
      <path d="M10 3 5 8l5 5" />
    </svg>
  );
}

export function IconChevronRight(props: IconProps) {
  return (
    <svg {...base(props.size ?? 16, props)}>
      <path d="m6 3 5 5-5 5" />
    </svg>
  );
}

export function IconMinus(props: IconProps) {
  return (
    <svg {...base(props.size ?? 15, props)}>
      <path d="M3 8h10" />
    </svg>
  );
}

/**
 * Die Pulslinie: schmale EKG-Linie, deren durchgezogener Teil (0–100)
 * dem Tagesfortschritt entspricht. Dekorativer Zusatz zur Zahlen-Anzeige,
 * daher `aria-hidden` – der Wert steht in der Statistikzeile.
 */
export function PulseLine({ percent }: { percent: number }) {
  const clamped = Math.min(100, Math.max(0, percent));
  // pathLength=100 → Dashoffset ist direkt das Prozent (ohne Messung).
  return (
    <svg
      className="pulse"
      viewBox="0 0 240 44"
      preserveAspectRatio="none"
      aria-hidden="true"
    >
      <path
        className="pulse__base"
        d="M0 26 H68 Q76 19 84 26 H98 L106 6 L116 40 L124 26 H138 Q146 19 154 26 H240"
        pathLength={100}
      />
      <path
        className="pulse__overlay"
        d="M0 26 H68 Q76 19 84 26 H98 L106 6 L116 40 L124 26 H138 Q146 19 154 26 H240"
        pathLength={100}
        strokeDasharray="100"
        strokeDashoffset={100 - clamped}
      />
    </svg>
  );
}

import type { DayKey } from '../lib/types';
import type { DayStats } from '../state/store';
import { addDays, formatLong, isFuture, isToday } from '../lib/dates';
import { PulseLine } from './PulseLine';
import { IconChevronLeft, IconChevronRight } from './icons';

interface DayHeaderProps {
  day: DayKey;
  stats: DayStats;
  onSelectDay: (day: DayKey) => void;
}

/** Kopfbereich: Tagesnavigation, Datum, Pulslinie und Instrumenten-Anzeige. */
export function DayHeader({ day, stats, onSelectDay }: DayHeaderProps) {
  const today = isToday(day);
  const future = isFuture(day);

  return (
    <section className="day" aria-label="Tagesübersicht">
      <nav className="day__nav" aria-label="Tagesnavigation">
        <button
          type="button"
          className="navbtn"
          onClick={() => onSelectDay(addDays(day, -1))}
          aria-label="Vorheriger Tag"
        >
          <IconChevronLeft />
        </button>
        <button
          type="button"
          className={`navbtn navbtn--today${today ? ' is-active' : ''}`}
          onClick={() => onSelectDay(addDays(day, 0))}
          disabled={today}
        >
          Heute
        </button>
        <button
          type="button"
          className="navbtn"
          onClick={() => onSelectDay(addDays(day, 1))}
          aria-label="Nächster Tag"
        >
          <IconChevronRight />
        </button>
      </nav>

      <h1 className="day__title">
        {formatLong(day)}
        {future && <span className="day__tag">künftiger Tag</span>}
        {!today && !future && <span className="day__tag">vergangener Tag</span>}
      </h1>

      <PulseLine percent={stats.percent} />

      <dl className="stats">
        <div className="stat">
          <dt className="stat__label">Erledigt</dt>
          <dd className="stat__value">{stats.done}</dd>
        </div>
        <div className="stat">
          <dt className="stat__label">Offen</dt>
          <dd className="stat__value">{stats.open}</dd>
        </div>
        <div className="stat">
          <dt className="stat__label">Fortschritt</dt>
          <dd className="stat__value">{stats.percent} %</dd>
        </div>
      </dl>

      {future && (
        <p className="day__note">
          Dies ist ein künftiger Tag – hier kann noch nichts abgehackt werden.
        </p>
      )}
      {!future && stats.total > 0 && stats.open === 0 && (
        <p className="day__note day__note--done">Alles für diesen Tag erledigt.</p>
      )}
    </section>
  );
}

import type { Activity, DayKey } from '../lib/types';
import { countFor, isDone } from '../state/store';
import { IconCheck, IconMinus, IconPencil, IconTrash } from './icons';

interface ActivityRowProps {
  activity: Activity;
  day: DayKey;
  /** Künftiger Tag → Abhaken gesperrt. */
  future: boolean;
  onToggle: () => void;
  onDecrement: () => void;
  onEdit: () => void;
  onDelete: () => void;
}

/** Eine Zeile der Tagesliste. */
export function ActivityRow({
  activity,
  day,
  future,
  onToggle,
  onDecrement,
  onEdit,
  onDelete,
}: ActivityRowProps) {
  const data = null; // Platzhalter entfernt – siehe unten
  void data;
  return <RowInner {...{ activity, day, future, onToggle, onDecrement, onEdit, onDelete }} />;
}

function RowInner({
  activity,
  day,
  future,
  onToggle,
  onDecrement,
  onEdit,
  onDelete,
}: ActivityRowProps & { data?: unknown }) {
  return null;
}

import type { Activity } from '../lib/types';
import { IconCheck, IconMinus, IconPencil, IconTrash } from './icons';

interface ActivityRowProps {
  activity: Activity;
  /** Zählstand für den angezeigten Tag (0..target). */
  count: number;
  /** Erledigt = count erreicht das Tagesziel. */
  done: boolean;
  /** Künftiger Tag → Abhaken gesperrt. */
  future: boolean;
  onToggle: () => void;
  onDecrement: () => void;
  onEdit: () => void;
  onDelete: () => void;
}

/**
 * Eine Zeile der Tagesliste: großer Toggle-Kreis (primäre Aktion), Name mit
 * optionaler Beschreibung, Zähl-Chip bei Tagesziel > 1, Edit-/Delete-Buttons.
 */
export function ActivityRow({
  activity,
  count,
  done,
  future,
  onToggle,
  onDecrement,
  onEdit,
  onDelete,
}: ActivityRowProps) {
  const target = Math.max(activity.target, 1);
  const counting = target > 1;

  let toggleLabel: string;
  if (done) {
    toggleLabel = counting
      ? `„${activity.name}“ ist erledigt – auf 0 zurücksetzen`
      : `„${activity.name}“ wieder offen machen`;
  } else if (counting) {
    toggleLabel = `Fortschritt für „${activity.name}“: ${count} von ${target} – abhaken`;
  } else {
    toggleLabel = `„${activity.name}“ abhaken`;
  }

  return (
    <li className="row">
      <button
        type="button"
        className={`row__check${done ? ' is-done' : ''}`}
        aria-pressed={done}
        aria-label={toggleLabel}
        disabled={future}
        onClick={onToggle}
      >
        {done ? (
          <IconCheck size={13} />
        ) : counting && count > 0 ? (
          <span className="row__count-num">{count}</span>
        ) : null}
      </button>

      <div className="row__main">
        <span className={`row__name${done ? ' is-done' : ''}`}>{activity.name}</span>
        {activity.description !== '' && (
          <span className="row__desc">{activity.description}</span>
        )}
      </div>

      {counting && <span className="row__chip" aria-hidden="true">{count}/{target}</span>}

      <span className="row__actions">
        {count > 0 && !future && (
          <button
            type="button"
            className="iconbtn"
            onClick={onDecrement}
            aria-label={`Einen Abhak-Schritt für „${activity.name}“ rückgängig machen`}
            title="Einen Schritt rückgängig"
          >
            <IconMinus />
          </button>
        )}
        <button
          type="button"
          className="iconbtn"
          onClick={onEdit}
          aria-label={`„${activity.name}“ bearbeiten`}
        >
          <IconPencil />
        </button>
        <button
          type="button"
          className="iconbtn iconbtn--danger"
          onClick={onDelete}
          aria-label={`„${activity.name}“ löschen`}
        >
          <IconTrash />
        </button>
      </span>
    </li>
  );
}

import type { Activity, AppData, DayKey } from '../lib/types';
import { countFor, isDone } from '../state/store';
import { isFuture } from '../lib/dates';
import { ActivityRow } from './ActivityRow';
import { EmptyState } from './EmptyState';

interface ActivityListProps {
  data: AppData;
  day: DayKey;
  onToggle: (activity: Activity) => void;
  onDecrement: (activity: Activity) => void;
  onEdit: (activity: Activity) => void;
  onDelete: (activity: Activity) => void;
  onAdd: () => void;
}

/** Die Tagesliste mit Empty-State. */
export function ActivityList({
  data,
  day,
  onToggle,
  onDecrement,
  onEdit,
  onDelete,
  onAdd,
}: ActivityListProps) {
  const future = isFuture(day);

  if (data.activities.length === 0) {
    return (
      <section aria-label="Aktivitäten">
        <h2 className="section__label">Aktivitäten</h2>
        <EmptyState onAdd={onAdd} />
      </section>
    );
  }

  return (
    <section aria-label="Aktivitäten">
      <h2 className="section__label">Aktivitäten</h2>
      <ul className="list">
        {data.activities.map((activity) => (
          <ActivityRow
            key={activity.id}
            activity={activity}
            day={day}
            count={countFor(data, day, activity)}
            done={isDone(data, day, activity)}
            future={future}
            onToggle={() => onToggle(activity)}
            onDecrement={() => onDecrement(activity)}
            onEdit={() => onEdit(activity)}
            onDelete={() => onDelete(activity)}
          />
        ))}
      </ul>
    </section>
  );
}

/** Leerer Zustand: Einladung zur ersten Aktivität, keine Stimmung, nur Richtung. */
export function EmptyState({ onAdd }: { onAdd: () => void }) {
  return (
    <div className="empty">
      <h2 className="empty__title">Noch keine Aktivitäten</h2>
      <p className="empty__text">
        Füge deine erste Aktivität hinzu – zum Beispiel „Morgens laufen“ oder
        „8 Gläser Wasser“.
      </p>
      <button type="button" className="btn btn--primary" onClick={onAdd}>
        Aktivität hinzufügen
      </button>
    </div>
  );
}

import type { BannerTone } from '../lib/types';

/** Leichtes Hinweosbanner (z. B. nicht lesbare gespeicherte Daten). */
export function Banner({
  tone,
  children,
  onDismiss,
}: {
  tone: BannerTone;
  children: React.ReactNode;
  onDismiss?: () => void;
}) {
  return (
    <div className={`banner banner--${tone}`} role="status">
      <div className="banner__text">{children}</div>
      {onDismiss && (
        <button
          type="button"
          className="banner__dismiss"
          onClick={onDismiss}
          aria-label="Hinweis ausblenden"
        >
          ✕
        </button>
      )}
    </div>
  );
}

