/* ============================================================
   PulseBoard — Design-Tokens
   Konzept: „Ruhiges Instrument“ (siehe PLAN.md)
   ============================================================ */

:root {
  color-scheme: light dark;

  --paper: #f4f4f1;
  --surface: #ffffff;
  --ink: #191c1a;
  --ink-soft: #6a716b;
  --pulse: #0e7a66;
  --on-pulse: #ffffff;
  --pulse-soft: rgba(14, 122, 102, 0.12);
  --danger: #b23a2a;
  --danger-soft: rgba(178, 58, 42, 0.09);
  --line: #e1e3dd;

  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
    "Helvetica Neue", Arial, sans-serif;
  --font-serif: "Iowan Old Style", "Palatino Linotype", Palatino, Georgia,
    serif;
  --font-mono: ui-monospace, "SF Mono", "Cascadia Mono", Menlo, Consolas,
    monospace;

  --radius: 8px;
}

@media (prefers-color-scheme: dark) {
  :root {
    --paper: #141614;
    --surface: #1c1f1c;
    --ink: #e6e8e3;
    --ink-soft: #969c93;
    --pulse: #54bfa2;
    --on-pulse: #10201b;
    --pulse-soft: rgba(84, 191, 162, 0.14);
    --danger: #e0785f;
    --danger-soft: rgba(224, 120, 95, 0.12);
    --line: #2a2e29;
  }
}

/* ---------- Basis ---------- */

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
}

body {
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font-sans);
  font-size: 15px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

h1,
h2,
h3 {
  margin: 0;
}

button {
  font: inherit;
}

:focus-visible {
  outline: 2px solid var(--pulse);
  outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
  }
}

/* ---------- Layout ---------- */

.shell {
  max-width: 680px;
  margin: 0 auto;
  padding: 0 20px 96px;
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 0;
  border-bottom: 1px solid var(--line);
}

.wordmark {
  font-weight: 650;
  font-size: 15px;
  letter-spacing: -0.01em;
}

.section__label {
  font-size: 13px;
  font-weight: 550;
  color: var(--ink-soft);
  margin: 0 0 8px;
}

/* ---------- Tageskopf ---------- */

.day {
  padding-top: 26px;
}

.day__nav {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 18px;
}

.navbtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 32px;
  height: 32px;
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: transparent;
  color: var(--ink);
  cursor: pointer;
  transition: border-color 120ms ease;
}

.navbtn:hover:not(:disabled) {
  border-color: var(--pulse);
  color: var(--pulse);
}

.navbtn:disabled {
  opacity: 0.45;
  cursor: default;
}

.navbtn--today {
  font-size: 13.5px;
}

.navbtn--today.is-active {
  background: var(--pulse-soft);
  border-color: transparent;
  color: var(--pulse);
}

.day__title {
  font-family: var(--font-serif);
  font-size: 30px;
  font-weight: 550;
  line-height: 1.25;
  letter-spacing: -0.01em;
  margin-bottom: 14px;
}

.day__tag {
  font-family: var(--font-sans);
  font-size: 13px;
  font-weight: 450;
  color: var(--ink-soft);
  margin-left: 10px;
  letter-spacing: 0;
}

/* Pulslinie: das eine mutige Element */
.pulse {
  display: block;
  width: 100%;
  height: 44px;
  margin-bottom: 4px;
}

.pulse__base {
  fill: none;
  stroke: var(--line);
  stroke-width: 2;
}

.pulse__overlay {
  fill: none;
  stroke: var(--pulse);
  stroke-width: 2.5;
  stroke-linecap: round;
  transition: stroke-dashoffset 250ms ease;
}

/* Instrumenten-Anzeige */
.stats {
  display: flex;
  gap: 32px;
  margin: 10px 0 22px;
  padding: 12px 0;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.stat {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.stat__label {
  font-size: 13px;
  color: var(--ink-soft);
}

.stat__value {
  font-family: var(--font-mono);
  font-size: 16px;
  margin: 0;
  font-variant-numeric: tabular-nums;
}

.day__note {
  font-size: 13.5px;
  color: var(--ink-soft);
  margin: -10px 0 18px;
}

.day__note--done {
  color: var(--pulse);
}

/* ---------- Liste ---------- */

.list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 0;
  border-bottom: 1px solid var(--line);
}

.row:first-child {
  padding-top: 4px;
}

.row__check {
  flex: none;
  width: 24px;
  height: 24px;
  padding: 0;
  border-radius: 50%;
  border: 1.5px solid var(--ink-soft);
  background: transparent;
  color: var(--on-pulse);
  display: grid;
  place-items: center;
  cursor: pointer;
  transition: background-color 120ms ease, border-color 120ms ease,
    transform 80ms ease;
}

.row__check:hover:not(:disabled) {
  border-color: var(--pulse);
}

.row__check:active:not(:disabled) {
  transform: scale(0.9);
}

.row__check:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.row__check.is-done {
  background: var(--pulse);
  border-color: var(--pulse);
}

.row__count-num {
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--pulse);
  font-weight: 600;
}

.row__main {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.row__name {
  font-weight: 550;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.row__name.is-done {
  color: var(--ink-soft);
  text-decoration: line-through;
  text-decoration-color: color-mix(in srgb, var(--ink-soft) 55%, transparent);
}

.row__desc {
  font-size: 13px;
  color: var(--ink-soft);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.row__chip {
  flex: none;
  font-family: var(--font-mono);
  font-size: 12px;
  color: var(--ink-soft);
  font-variant-numeric: tabular-nums;
}

.row__actions {
  flex: none;
  display: flex;
  align-items: center;
  gap: 2px;
  opacity: 0.65;
  transition: opacity 120ms ease;
}

.row:hover .row__actions,
.row:focus-within .row__actions {
  opacity: 1;
}

.iconbtn {
