  padding: 0;
}

.cat__row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 7px 0;
}

.cat__name {
  flex: none;
  width: 130px;
  font-size: 14px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cat__bar {
  flex: 1;
  height: 6px;
  border-radius: 3px;
  background: var(--line);
  overflow: hidden;
}

.cat__fill {
  display: block;
  height: 100%;
  border-radius: 3px;
  background: var(--pulse);
  transition: width 200ms ease;
}

.cat__count {
  flex: none;
  width: 42px;
  text-align: right;
  font-family: var(--font-mono);
  font-size: 12px;
  color: var(--ink-soft);
  font-variant-numeric: tabular-nums;
}

/* ---------- Empty State ---------- */

.empty {
  margin-top: 14px;
  padding: 40px 24px;
  border: 1px dashed var(--line);
  border-radius: 12px;
  text-align: center;
}

.empty__title {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 6px;
}

.empty__text {
  font-size: 14px;
  color: var(--ink-soft);
  margin: 0 auto 18px;
  max-width: 40ch;
}

/* ---------- Banner ---------- */

.banner {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  margin: 18px 0 0;
  padding: 12px 14px;
  border-radius: 10px;
  font-size: 14px;
  line-height: 1.45;
}

.banner--danger {
  background: var(--danger-soft);
  color: var(--danger);
}

.banner--warning {
  background: var(--pulse-soft);
  color: var(--ink);
}

.banner__text {
  flex: 1;
}

.banner__dismiss {
  flex: none;
  border: none;
  background: transparent;
  color: inherit;
  cursor: pointer;
  padding: 2px 4px;
  opacity: 0.7;
}

.banner__dismiss:hover {
  opacity: 1;
}

/* ---------- Dialog ---------- */

.dialog {
  width: min(480px, calc(100vw - 32px));
  margin: auto;
  padding: 0;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--surface);
  color: var(--ink);
  box-shadow: 0 18px 50px rgba(0, 0, 0, 0.16);
}

.dialog::backdrop {
  background: rgba(12, 14, 13, 0.45);
}

@media (prefers-color-scheme: dark) {
  .dialog::backdrop {
    background: rgba(0, 0, 0, 0.6);
  }
}

.dialog__title {
  padding: 20px 20px 0;
  font-size: 17px;
  font-weight: 650;
}

.dialog__form {
  padding: 16px 20px 20px;
}

.field {
  margin-bottom: 14px;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.field label {
  font-size: 13px;
  font-weight: 550;
  color: var(--ink-soft);
}

.field input,
.field textarea {
  width: 100%;
  padding: 8px 10px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--paper);
  color: var(--ink);
  font: inherit;
  font-size: 14.5px;
}

.field textarea {
  resize: vertical;
  min-height: 54px;
}

.field__hint {
  margin: 0;
  font-size: 12px;
  color: var(--ink-soft);
}

.dialog__grid {
  display: grid;
  grid-template-columns: 1fr 110px;
  gap: 14px;
}

@media (max-width: 460px) {
  .dialog__grid {
    grid-template-columns: 1fr;
  }
}

.dialog__error {
  margin: 0 0 12px;
  font-size: 13.5px;
  color: var(--danger);
}

.dialog__actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 18px;
}

/* ---------- Toasts ---------- */

.toasts {
  position: fixed;
  left: 50%;
  bottom: 16px;
  transform: translateX(-50%);
  z-index: 50;
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: min(440px, calc(100vw - 32px));
}

.toasts:empty {
  display: none;
}

.toast {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 12px;
  border-radius: 10px;
  background: var(--ink);
  color: var(--paper);
  font-size: 14px;
  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.18);
}

.toast--error {
  background: var(--danger);
  color: #fff;
}

.toast__close {
  border: none;
  background: transparent;
  color: inherit;
  cursor: pointer;
  opacity: 0.65;
  padding: 0 2px;
}

.toast__close:hover {
  opacity: 1;
}

/* ---------- Update-Prompt ---------- */

.update {
  position: fixed;
  right: 16px;
  bottom: 16px;
  z-index: 40;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--surface);
  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.14);
  font-size: 13.5px;
}

/* ---------- Kleingeräte ---------- */

@media (max-width: 480px) {
  .shell {
    padding: 0 16px 96px;
  }

  .day__title {
    font-size: 25px;
  }

  .stats {
    gap: 22px;
  }

  .cat__name {
    width: 96px;
  }
}

/**
 * Erzeugt die PWA-Icons als Platzhalter-PNGs komplett lokal (kein externes
 * Webdienst, keine Bild-Bibliothek): reines zlib + handgerollter PNG-Encoder.
 *
 * Motiv: Teal-Fläche, weiße Pulslinie (QPS-artiger Spike) – dieselbe Linie
 * wie in der App (src/components/PulseLine.tsx).
 *
 * Aufruf: node scripts/generate-icons.mjs  →  public/icons/icon-{192,512}.png, maskable-512.png
 */
import { deflateSync } from 'node:zlib';
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const outDir = join(root, 'public', 'icons');

/* ---------- PNG-Encoder (8-bit RGB) ---------- */

const CRC_TABLE = (() => {
  const table = new Int32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    table[n] = c;
  }
  return table;
})();

function crc32(buf) {
  let c = 0xffffffff;
  for (let i = 0; i < buf.length; i++) {
    c = CRC_TABLE[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
  }
  return (c ^ 0xffffffff) >>> 0;
}

function chunk(type, data) {
  const len = Buffer.alloc(4);
  len.writeUInt32BE(data.length);
  const typeBuf = Buffer.from(type, 'ascii');
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(Buffer.concat([typeBuf, data])));
  return Buffer.concat([len, typeBuf, data, crc]);
}

function encodePng(width, height, pixelFn) {
  const raw = Buffer.alloc((width * 3 + 1) * height);
  let o = 0;
  for (let y = 0; y < height; y++) {
    raw[o++] = 0; // Filter: none
    for (let x = 0; x < width; x++) {
      const [r, g, b] = pixelFn(x, y);
      raw[o++] = r;
      raw[o++] = g;
      raw[o++] = b;
    }
  }
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(width, 0);
  ihdr.writeUInt32BE(height, 4);
  ihdr[8] = 8; // Bitstärke
  ihdr[9] = 2; // color type: truecolor
  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk('IHDR', ihdr),
    chunk('IDAT', deflateSync(raw, { level: 9 })),
    chunk('IEND', Buffer.alloc(0)),
  ]);
}

/* ---------- Zeichen-Hilfen ---------- */

function hexToRgb(hex) {
  const h = hex.replace('#', '');
  return [
    parseInt(h.slice(0, 2), 16),
    parseInt(h.slice(2, 4), 16),
    parseInt(h.slice(4, 6), 16),
  ];
}

function inRoundedRect(x, y, size, radius) {
  if (x < 0 || y < 0 || x >= size || y >= size) return false;
  if (x >= radius && x <= size - radius) return true;
  if (y >= radius && y <= size - radius) return true;
  const cx = x < radius ? radius : size - radius;
  const cy = y < radius ? radius : size - radius;
  const dx = x - cx;
  const dy = y - cy;
  return dx * dx + dy * dy <= radius * radius;
}

/** Distanz Punkt → Streckenabschnitt, Punkte als [x, y]. */
function distToSegment(px, py, ax, ay, bx, by) {
  const vx = bx - ax;
  const vy = by - ay;
  const wx = px - ax;
  const wy = py - ay;
  const len2 = vx * vx + vy * vy;
  const t = len2 === 0 ? 0 : Math.max(0, Math.min(1, (wx * vx + wy * vy) / len2));
  const dx = px - (ax + t * vx);
  const dy = py - (ay + t * vy);
  return Math.sqrt(dx * dx + dy * dy);
}

// Relative Wegpunkte der Pulslinie (wie in der App, viewBox 240×44, Basis y=26).
const PULSE_POINTS = [
  [0.2, 0.59],
  [0.4, 0.59],
  [0.47, 0.16],
  [0.56, 0.9],
  [0.63, 0.59],
  [0.8, 0.59],
];

function makeIcon(size, { rounded, safeZone = 1 }) {
  const bg = hexToRgb('#0e7a66');
  const fg = hexToRgb('#f4f4f1');
  const radius = rounded ? size * 0.22 : 0;
  const strokeWidth = size * 0.045 * safeZone;
  // Skalierung in den Safe Zone (maskable: 0.8), zentriert.
  const scale = safeZone;
  const off = (1 - scale) / 2;

  const segments = [];
  for (let i = 0; i < PULSE_POINTS.length - 1; i++) {
    const [x1, y1] = PULSE_POINTS[i];
    const [x2, y2] = PULSE_POINTS[i + 1];
    segments.push([
      (off + x1 * scale) * size,
      (off + y1 * scale) * size,
      (off + x2 * scale) * size,
      (off + y2 * scale) * size,
    ]);
  }

  return encodePng(size, size, (x, y) => {
    if (rounded ? inRoundedRect(x, y, size, radius) : true) {
      // anti-aliased Edge für den Kontur des Bildes
      const onLine = segments.some(
        ([ax, ay, bx, by]) => distToSegment(x, y, ax, ay, bx, by) <= strokeWidth / 2,
      );
      if (onLine) return fg;
      return bg;
    }
    return [0, 0, 0]; // transparenter Rand (wird hier nicht gezeichnet, nur RGB)
  });
}

/* ---------- Ausgeben ---------- */

mkdirSync(outDir, { recursive: true });

const outputs = [
  [join(outDir, 'icon-192.png'), () => makeIcon(192, { rounded: true })],
  [join(outDir, 'icon-512.png'), () => makeIcon(512, { rounded: true })],
  [
    join(outDir, 'maskable-512.png'),
    () => makeIcon(512, { rounded: false, safeZone: 0.78 }),
  ],
];

for (const [file, fn] of outputs) {
  writeFileSync(file, fn());
  console.log(`✓ ${file}`);
}
console.log('Icons erzeugt.');

