/**
 * Zentrale Uhr: alle Datumsfunktionen fragen `now()` ab. Tests setzen per
 * `setClock()` ein festes Datum und erhalten so deterministische Tests,
 * ohne Fake-Timer (die z. B. user-event brechen würden).
 */
let override: Date | null = null;

export function setClock(date: Date | null): void {
  override = date;
}

export function now(): Date {
  return override ?? new Date();
}

import type { DayKey } from './types';
import { now } from './clock';

const KEY_RE = /^(\d{4})-(\d{2})-(\d{2})$/;

/** `Date` → lokaler DayKey (`YYYY-MM-DD`). */
export function toKey(date: Date): DayKey {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}

/** DayKey für "heute" (lokale Zeit). */
export function todayKey(at: Date = now()): DayKey {
  return toKey(at);
}

/** DayKey → `Date` auf 0:00 Uhr lokaler Zeit; ungültige Keys liefern `null`. */
export function fromKey(key: DayKey): Date | null {
  const m = KEY_RE.exec(key);
  if (!m) return null;
  const date = new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
  return Number.isNaN(date.getTime()) ? null : date;
}

/** Strikt prüfen, ob der String ein gültiger lokaler Kalendertag ist. */
export function isValidKey(key: string): boolean {
  const date = fromKey(key);
  if (!date) return false;
  // fromKey normalisiert (z. B. 2026-02-31 → 3. März), deshalb rückprüfen.
  return toKey(date) === key;
}

/** DayKey um `delta` Tage verschieben (negativ erlaubt). */
export function addDays(key: DayKey, delta: number): DayKey {
  const date = fromKey(key) ?? new Date();
  const shifted = new Date(date);
  shifted.setDate(shifted.getDate() + delta);
  return toKey(shifted);
}

/** Ist der Tag streng in der Zukunft (relativ zu `at`)? */
export function isFuture(key: DayKey, at: Date = now()): boolean {
  return key > todayKey(at);
}

/** Ist der Tag der heutige? */
export function isToday(key: DayKey, at: Date = now()): boolean {
  return key === todayKey(at);
}

/** "Donnerstag, 27. September" – lange Form für den Kopfbereich. */
export function formatLong(key: DayKey): string {
  const date = fromKey(key);
  if (!date) return key;
  return new Intl.DateTimeFormat('de-DE', {
    weekday: 'long',
    day: 'numeric',
    month: 'long',
  }).format(date);
}

/** "27. Sep." – kurze Form. */
export function formatShort(key: DayKey): string {
  const date = fromKey(key);
  if (!date) return key;
  return new Intl.DateTimeFormat('de-DE', {
    day: 'numeric',
    month: 'short',
  }).format(date);
}

import '@testing-library/jest-dom/vitest';
import { cleanup } from '@testing-library/react';
import { afterEach } from 'vitest';
import { setClock } from '../lib/clock';

afterEach(() => {
  cleanup();
  window.localStorage.clear();
  window.location.hash = '';
  setClock(null);
});

// jsdom hat <dialog> nur teilweise implementiert: showModal/hasFocus fehlen je
// nach Version. Minimalpolyfill, damit die App-Komponente portabel läuft.
if (typeof HTMLDialogElement !== 'undefined') {
  const proto = HTMLDialogElement.prototype as HTMLDialogElement & {
    showModal?: unknown;
    close?: unknown;
  };
  if (typeof proto.showModal !== 'function') {
    proto.showModal = function () {
      this.open = true;
    };
  }
  if (typeof proto.close !== 'function') {
    proto.close = function () {
      this.open = false;
      this.dispatchEvent(new Event('close'));
    };
  }
}

/** Vitest-Stub für das virtuelle Modul `virtual:pwa-register` (PWA in Tests aus). */
export default function registerSW(
  _options?: {
    immediate?: boolean;
    onNeedRefresh?: () => void;
    onOfflineReady?: () => void;
    onRegisteredSW?: (url: string, registration: unknown) => void;
  },
): (reload?: boolean) => Promise<void> {
  return () => Promise.resolve();
}

import { describe, expect, it } from 'vitest';
import {
  addDays,
  formatLong,
  formatShort,
  fromKey,
  isFuture,
  isToday,
  isValidKey,
  toKey,
  todayKey,
} from './dates';
import { setClock } from './clock';

describe('dates', () => {
  it('toKey/formatLong-Loop: Datum → Key → Datum', () => {
    const date = new Date(2026, 8, 27); // 27. September 2026
    expect(toKey(date)).toBe('2026-09-27');
    const back = fromKey('2026-09-27');
    expect(back).not.toBeNull();
    expect(toKey(back as Date)).toBe('2026-09-27');
  });

  it('ruft zweistellige Monate/Tage korrekt auf', () => {
    expect(toKey(new Date(2026, 0, 5))).toBe('2026-01-05');
    expect(toKey(new Date(2025, 11, 31))).toBe('2025-12-31');
  });

  it('isValidKey akzeptiert nur echte Kalendertage', () => {
    expect(isValidKey('2026-09-27')).toBe(true);
    expect(isValidKey('2024-02-29')).toBe(true); // Schaltjahr
    expect(isValidKey('2026-02-29')).toBe(false);
    expect(isValidKey('2026-00-10')).toBe(false);
    expect(isValidKey('2026-13-01')).toBe(false);
    expect(isValidKey('27.09.2026')).toBe(false);
    expect(isValidKey('')).toBe(false);
  });

  it('addDays arbeitet über Monats- und Jahresgrenzen', () => {
    expect(addDays('2026-09-27', 1)).toBe('2026-09-28');
    expect(addDays('2026-09-30', 1)).toBe('2026-10-01');
    expect(addDays('2026-01-01', -1)).toBe('2025-12-31');
    expect(addDays('2026-03-31', 1)).toBe('2026-04-01');
  });

  it('isFuture/isToday mit festgelegter Uhr', () => {
    setClock(new Date(2026, 8, 27, 12));
    expect(isToday('2026-09-27')).toBe(true);
    expect(isToday('2026-09-26')).toBe(false);
    expect(isFuture('2026-09-28')).toBe(true);
    expect(isFuture('2026-09-27')).toBe(false);
    expect(isFuture('2026-09-26')).toBe(false);
    expect(todayKey()).toBe('2026-09-27');
  });

  it('formatiert Datum deutsch', () => {
    // 27. September 2026 ist ein Samstag.
    expect(formatLong('2026-09-27')).toBe('Samstag, 27. September');
    expect(formatShort('2026-09-27')).toMatch(/27\.\s*Sep/);
  });
});

