import { beforeEach, describe, expect, it, vi } from 'vitest';
import {
  SCHEMA_VERSION,
  STORAGE_KEY,
  emptyData,
  load,
  parseStored,
  save,
} from './storage';
import type { AppData } from './types';

function writeRaw(raw: string) {
  window.localStorage.setItem(STORAGE_KEY, raw);
}

function validData(): AppData {
  return {
    version: SCHEMA_VERSION,
    activities: [
      {
        id: 'a1',
        name: 'Morgens laufen',
        description: '',
        category: 'Gesundheit',
        target: 3,
        createdAt: '2026-09-27T08:00:00.000Z',
      },
      {
        id: 'a2',
        name: 'E-Mails aufräumen',
        description: 'einmal täglich',
        category: 'Arbeit',
        target: 1,
        createdAt: '2026-09-27T08:05:00.000Z',
      },
    ],
    progress: {
      '2026-09-27': { a1: 2, a2: 1 },
      '2026-09-26': { a1: 3 },
    },
  };
}

describe('storage', () => {
  beforeEach(() => {
    window.localStorage.clear();
  });

  it('liefert leeres Dokument, wenn nichts gespeichert ist', () => {
    const { data, recovery } = load();
    expect(recovery).toBe('empty');
    expect(data.activities).toEqual([]);
    expect(data.progress).toEqual({});
  });

  it('Roundtrip: save → load behält alle Tage separat bei', () => {
    const data = validData();
    expect(save(data)).toBe(true);
    const { data: back, recovery } = load();
    expect(recovery).toBe('ok');
    expect(back).toEqual(data);
    // Tage überschreiben sich nicht:
    expect(back.progress['2026-09-27']).toEqual({ a1: 2, a2: 1 });
    expect(back.progress['2026-09-26']).toEqual({ a1: 3 });
  });

  it('korruptes JSON → leeres Dokument + Recovery "corrupt", kein Crash', () => {
    writeRaw('das ist kein JSON {{{');
    const { data, recovery } = load();
    expect(recovery).toBe('corrupt');
    expect(data.activities).toEqual([]);
  });

  it('falscher Wurzeltyp → Recovery "corrupt"', () => {
    writeRaw(JSON.stringify(['a', 'b']));
    const { data, recovery } = load();
    expect(recovery).toBe('corrupt');
    expect(data.activities).toEqual([]);

    writeRaw(JSON.stringify('"nur ein string"'));
    expect(load().recovery).toBe('corrupt');
  });

  it('alte Version → Daten werden gerettet und als "migrated" markiert', () => {
    const data = validData();
    writeRaw(JSON.stringify({ ...data, version: 0 }));
    const { data: back, recovery } = load();
    expect(recovery).toBe('migrated');
    expect(back.version).toBe(SCHEMA_VERSION);
    expect(back.activities.map((a) => a.id)).toEqual(['a1', 'a2']);
  });

  it('sanitize: leere Namen und doppelte IDs fallen raus', () => {
    const { data, migrated } = parseStored({
      version: SCHEMA_VERSION,
      activities: [
        { id: 'x', name: '   ' },
        { id: 'x', name: 'Doppel-ID, erster gültiger' },
        { id: 'x', name: 'Doppel-ID, zweiter wird verworfen' },
        { name: 'Keine ID' },
        { id: 'ok', name: 'Gültig' },
      ],
      progress: {},
    });
    expect(migrated).toBe(false);
    expect(data).not.toBeNull();
    expect(data as AppData).toMatchObject({
      activities: [
        { id: 'x', name: 'Doppel-ID, erster gültiger' },
        { id: 'ok', name: 'Gültig' },
      ],
    });
  });

  it('sanitize: Ziel wird normalisiert (String, 0, NaN → 1)', () => {
    const { data } = parseStored({
      version: SCHEMA_VERSION,
      activities: [
        { id: 'a', name: 'A', target: '5' },
        { id: 'b', name: 'B', target: 0 },
        { id: 'c', name: 'C', target: Number.NaN },
      ],
      progress: {},
    });
    const byId = new Map((data as AppData).activities.map((a) => [a.id, a.target]));
    expect(byId.get('a')).toBe(5);
    expect(byId.get('b')).toBe(1);
    expect(byId.get('c')).toBe(1);
  });

  it('sanitize: fehlende Kategorie wird zu "Ohne Kategorie"', () => {
    const { data } = parseStored({
      version: SCHEMA_VERSION,
      activities: [{ id: 'a', name: 'A' }],
      progress: {},
    });
    expect((data as AppData).activities[0].category).toBe('Ohne Kategorie');
  });

  it('sanitize: ungelte Datums-Keys und tote Referenzen im Progress fallen raus', () => {
    const { data } = parseStored({
      version: SCHEMA_VERSION,
      activities: [{ id: 'a', name: 'A', target: 2 }],
      progress: {
        '2026-9-2': { a: 1 }, // ungültiges Format
        '2026-09-27': { a: 1, ghost: 3 }, // ghost: keine Aktivität
      },
    });
    expect(data).not.toBeNull();
    expect((data as AppData).progress).toEqual({ '2026-09-27': { a: 1 } });
  });

  it('sanitize: Zählstand wird auf 0..target geklemmt, negative Werte verworfen', () => {
    const { data } = parseStored({
      version: SCHEMA_VERSION,
      activities: [{ id: 'a', name: 'A', target: 2 }],
      progress: {
        '2026-09-27': { a: 99 },
        '2026-09-26': { a: -1 },
      },
    });
    expect((data as AppData).progress['2026-09-27']).toEqual({ a: 2 });
    expect((data as AppData).progress['2026-09-26']).toBeUndefined();
  });

  it('save meldet Fehler bei vollem/ge-sperrtem Speicher', () => {
    const spy = vi
      .spyOn(Storage.prototype, 'setItem')
      .mockImplementation(() => {
        throw new Error('QuotaExceededError');
      });
    expect(save(validData())).toBe(false);
    spy.mockRestore();
  });

  it('emptyData liefert versioniertes leeres Dokument', () => {
    expect(emptyData()).toEqual({ version: SCHEMA_VERSION, activities: [], progress: {} });
  });
});

import { beforeEach, describe, expect, it } from 'vitest';
import {
  categoryStats,
  countFor,
  freshData,
  isDone,
  reducer,
  statsForDay,
} from './store';
import { setClock } from '../lib/clock';
import type { AppData } from '../lib/types';

const TODAY = '2026-09-27';
const YESTERDAY = '2026-09-26';
const TOMORROW = '2026-09-28';

function seed(): AppData {
  const data = freshData();
  const withA = reducer(data, {
    type: 'activity/add',
    activity: { name: 'Morgens laufen', description: '', category: 'Gesundheit', target: 3 },
  });
  const withB = reducer(withA, {
    type: 'activity/add',
    activity: { name: 'E-Mails aufräumen', description: '', category: 'Arbeit', target: 1 },
  });
  const withC = reducer(withB, {
    type: 'activity/add',
    activity: { name: 'Räumen', description: '', category: 'Haushalt', target: 1 },
  });
  return withC;
}

function firstActivity(data: AppData) {
  return data.activities[0];
}

describe('store: Aktivitäten verwalten', () => {
  it('add: erstellt Aktivität mit id und createdAt', () => {
    const data = freshData();
    const next = reducer(data, {
      type: 'activity/add',
      activity: { name: 'Test', description: 'd', category: 'C', target: 1 },
    });
    expect(next.activities).toHaveLength(1);
    const activity = next.activities[0];
    expect(activity.id).not.toBe('');
    expect(activity.createdAt).not.toBe('');
    expect(next.activities[0].name).toBe('Test');
  });

  it('update: patcht nur das gegebene Feld', () => {
    const data = seed();
    const a = firstActivity(data);
    const next = reducer(data, {
      type: 'activity/update',
      id: a.id,
      patch: { name: 'Abends laufen', description: 'neu', category: a.category, target: 5 },
    });
    const updated = next.activities.find((x) => x.id === a.id);
    expect(updated?.name).toBe('Abends laufen');
    expect(updated?.description).toBe('neu');
    expect(updated?.target).toBe(5);
    // andere Aktivität bleibt unberührt
    expect(next.activities.filter((x) => x.id !== a.id)).toHaveLength(2);
  });

  it('delete: entfernt Aktivität UND bereinigt den Tagesstatus aller Tage', () => {
    let data = seed();
    const a = firstActivity(data);
    data = reducer(data, { type: 'progress/toggle', date: TODAY, id: a.id });
    data = reducer(data, { type: 'progress/toggle', date: YESTERDAY, id: a.id });
    expect(data.progress[TODAY]).toHaveProperty(a.id);
    expect(data.progress[YESTERDAY]).toHaveProperty(a.id);

    const next = reducer(data, { type: 'activity/delete', id: a.id });
    expect(next.activities.find((x) => x.id === a.id)).toBeUndefined();
    expect(next.progress[TODAY]).not.toHaveProperty(a.id);
    expect(next.progress[YESTERDAY]).not.toHaveProperty(a.id);
  });

  it('delete: nicht vorhandene ID → kein Fehler, kein Change', () => {
    const data = seed();
    expect(reducer(data, { type: 'activity/delete', id: 'keine' })).toBe(data);
  });
});

describe('store: Tagesstatus', () => {
  beforeEach(() => {
    setClock(new Date(2026, 8, 27, 12)); // heute = 2026-09-27
  });

  it('toggle mit Ziel 1: an/aus', () => {
    let data = seed();
    const a = firstActivity(data);
    data = reducer(data, { type: 'progress/toggle', date: TODAY, id: a.id });
    expect(countFor(data, TODAY, a)).toBe(1);
    expect(isDone(data, TODAY, a)).toBe(true);
    data = reducer(data, { type: 'progress/toggle', date: TODAY, id: a.id });
    expect(countFor(data, TODAY, a)).toBe(0);
    expect(isDone(data, TODAY, a)).toBe(false);
  });

  it('toggle mit Ziel 3: zählt hoch, bei Erreichen fertig, dann auf 0 zurück', () => {
    let data = seed();
    const a = firstActivity(data); // Ziel 3
    expect(countFor(data, TODAY, a)).toBe(0);
    data = reducer(data, { type: 'progress/toggle', date: TODAY, id: a.id });
    data = reducer(data, { type: 'progress/toggle', date: TODAY, id: a.id });
    expect(countFor(data, TODAY, a)).toBe(2);
    expect(isDone(data, TODAY, a)).toBe(false);
    data = reducer(data, { type: 'progress/toggle', date: TODAY, id: a.id });
    expect(countFor(data, TODAY, a)).toBe(3);
    expect(isDone(data, TODAY, a)).toBe(true);
    // weiterer Klick → Reset
    data = reducer(data, { type: 'progress/toggle', date: TODAY, id: a.id });
    expect(countFor(data, TODAY, a)).toBe(0);
  });

  it('decrement: geht einen Schritt zurück, Boden 0', () => {
    let data = seed();
    const a = firstActivity(data);
    data = reducer(data, { type: 'progress/toggle', date: TODAY, id: a.id });
    data = reducer(data, { type: 'progress/toggle', date: TODAY, id: a.id });
    data = reducer(data, { type: 'progress/decrement', date: TODAY, id: a.id });
    expect(countFor(data, TODAY, a)).toBe(1);
    data = reducer(data, { type: 'progress/decrement', date: TODAY, id: a.id });
    data = reducer(data, { type: 'progress/decrement', date: TODAY, id: a.id });
    expect(countFor(data, TODAY, a)).toBe(0);
  });

  it('Tage überschreiben sich nicht: Status je Datum isoliert', () => {
    let data = seed();
    const a = firstActivity(data);
    data = reducer(data, { type: 'progress/toggle', date: TODAY, id: a.id });
    data = reducer(data, { type: 'progress/toggle', date: YESTERDAY, id: a.id });
    expect(countFor(data, TODAY, a)).toBe(1);
    expect(countFor(data, YESTERDAY, a)).toBe(1);
    // nur heute weiterzählen → gestern bleibt
    data = reducer(data, { type: 'progress/toggle', date: TODAY, id: a.id });
    data = reducer(data, { type: 'progress/toggle', date: TODAY, id: a.id });
    expect(countFor(data, TODAY, a)).toBe(3);
    expect(countFor(data, YESTERDAY, a)).toBe(1);
  });

  it('toggle an futuristischem Tag wird abgelehnt (UI-Sperre + Reducer)', () => {
    const data = seed();
    const a = firstActivity(data);
    const before = data;
    const after = reducer(data, { type: 'progress/toggle', date: TOMORROW, id: a.id });
    expect(after).toBe(before); // Referenzgleich → kein Change
    const afterDec = reducer(data, { type: 'progress/decrement', date: TOMORROW, id: a.id });
    expect(afterDec).toBe(before);
  });

  it('toggle für unbekannte ID → kein Change', () => {
    const data = seed();
    expect(reducer(data, { type: 'progress/toggle', date: TODAY, id: 'keine' })).toBe(data);
  });
});

describe('store: Selectoren', () => {
  beforeEach(() => {
    setClock(new Date(2026, 8, 27, 12));
  });

  it('statsForDay: erledigt/offen/Prozent', () => {
    let data = seed(); // 3 Aktivitäten: Ziel 3, 1, 1
    expect(statsForDay(data, TODAY)).toEqual({ total: 3, done: 0, open: 3, percent: 0 });
    const a = firstActivity(data);
    const b = data.activities[1];
    data = reducer(data, { type: 'progress/toggle', date: TODAY, id: a.id }); // 1/3 → offen
    data = reducer(data, { type: 'progress/toggle', date: TODAY, id: b.id }); // fertig
    const stats = statsForDay(data, TODAY);
    expect(stats.total).toBe(3);
    expect(stats.done).toBe(1);
    expect(stats.open).toBe(2);
    expect(stats.percent).toBe(33);
  });

  it('statsForDay: leerer Tag → 0 % ohne NaN', () => {
    expect(statsForDay(freshData(), TODAY).percent).toBe(0);
  });

  it('categoryStats: gruppiert und alphabetisch (de)', () => {
    let data = seed();
    const a = firstActivity(data); // Gesundheit
    const b = data.activities[2]; // Haushalt
    data = reducer(data, { type: 'progress/toggle', date: TODAY, id: a.id });
    data = reducer(data, { type: 'progress/toggle', date: TODAY, id: b.id });
    const stats = categoryStats(data, TODAY);
    expect(stats.map((s) => s.category)).toEqual(['Arbeit', 'Gesundheit', 'Haushalt']);
    const gesund = stats.find((s) => s.category === 'Gesundheit');
    expect(gesund).toEqual({ category: 'Gesundheit', total: 1, done: 0 });
    const haushalt = stats.find((s) => s.category === 'Haushalt');
    expect(haushalt).toEqual({ category: 'Haushalt', total: 1, done: 1 });
  });

  it('data/replace: kompletter Reset', () => {
    const data = seed();
    const replaced = reducer(data, { type: 'data/replace', data: freshData() });
    expect(replaced.activities).toHaveLength(0);
    expect(replaced.progress).toEqual({});
  });
});

import { beforeEach, describe, expect, it } from 'vitest';
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import App from './App';
import { STORAGE_KEY } from './lib/storage';
import { setClock } from './lib/clock';

/** Fester "heute": Sonntag, 27. September 2026, 12 Uhr. */
beforeEach(() => {
  setClock(new Date(2026, 8, 27, 12));
});

async function openAddDialog(user: ReturnType<typeof userEvent.setup>) {
  // Es gibt (im leeren Zustand) 1–2 Buttons mit diesem Namen; den letzten nehmen.
  const buttons = screen.getAllByRole('button', { name: 'Aktivität hinzufügen' });
  await user.click(buttons[buttons.length - 1]);
  return screen.getByRole('dialog');
}

interface AddOptions {
  name: string;
  category?: string;
  target?: string; // String, weil Eingabefeld
  description?: string;
}

async function addActivity(
  user: ReturnType<typeof userEvent.setup>,
  options: AddOptions,
) {
  const dialog = await openAddDialog(user);
  await user.type(within(dialog).getByLabelText('Name'), options.name);
  if (options.category !== undefined) {
    await user.type(within(dialog).getByLabelText('Kategorie'), options.category);
  }
  if (options.target !== undefined) {
    await user.type(within(dialog).getByLabelText('Tagesziel'), options.target);
  }
  if (options.description !== undefined) {
    await user.type(within(dialog).getByLabelText('Beschreibung'), options.description);
  }
  await user.click(within(dialog).getByRole('button', { name: 'Speichern' }));
}

function dialogIsOpen() {
  return screen.queryByRole('dialog') !== null;
}

describe('App: Darstellung', () => {
  it('zeigt leeren Zustand mit Einladung, Datum und Wortmarke', () => {
    render(<App />);
    expect(screen.getByText('PulseBoard')).toBeInTheDocument();
    expect(screen.getByRole('heading', { level: 1 })).toHaveTextContent(
      'Sonntag, 27. September',
    );
    expect(screen.getByText('Noch keine Aktivitäten')).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Aktivität hinzufügen' })).toBeInTheDocument();
  });
});

describe('App: Aktivitäten verwalten', () => {
  it('Erstellen: Formular erzeugt Zeile mit Zähl-Chip bei Tagesziel > 1', async () => {
    const user = userEvent.setup();
    render(<App />);

    await addActivity(user, { name: 'Morgens laufen', category: 'Gesundheit', target: '3' });

    expect(dialogIsOpen()).toBe(false);
    expect(screen.getByText('Morgens laufen')).toBeInTheDocument();
    expect(screen.getByText('0/3')).toBeInTheDocument();
    // Kategorie-Vorschlag kommt aus dem Datalist-Bezug (Test auf Anwesenheit der Zeile reicht)
    expect(screen.getByRole('button', { name: '„Morgens laufen“ bearbeiten' })).toBeInTheDocument();
  });

  it('Erstellen: ohne Tagesziel wird einmal abgehackt (kein Chip)', async () => {
    const user = userEvent.setup();
    render(<App />);

    await addActivity(user, { name: 'E-Mails aufräumen' });

    expect(screen.getByText('E-Mails aufräumen')).toBeInTheDocument();
    expect(screen.queryByText(/0\/1/)).not.toBeInTheDocument();
  });

  it('Bearbeiten: Name und Ziel werden aktualisiert', async () => {
    const user = userEvent.setup();
    render(<App />);
    await addActivity(user, { name: 'Wasser trinken', target: '8' });

    await user.click(screen.getByRole('button', { name: '„Wasser trinken“ bearbeiten' }));
    const dialog = screen.getByRole('dialog');
    expect(within(dialog).getByRole('heading', { level: 2 })).toHaveTextContent(
      'Aktivität bearbeiten',
    );

    const nameField = within(dialog).getByLabelText('Name');
    await user.clear(nameField);
    await user.type(nameField, '8 Gläser Wasser');
    await user.click(within(dialog).getByRole('button', { name: 'Speichern' }));

    expect(dialogIsOpen()).toBe(false);
    expect(screen.getByText('8 Gläser Wasser')).toBeInTheDocument();
    expect(screen.getByText('0/8')).toBeInTheDocument();
  });

  it('Löschen: Zeile verschwindet, leere Liste zeigt Empty State wieder', async () => {
    const user = userEvent.setup();
    render(<App />);
    await addActivity(user, { name: 'Temporär' });

    await user.click(screen.getByRole('button', { name: '„Temporär“ löschen' }));

    expect(screen.queryByText('Temporär')).not.toBeInTheDocument();
    expect(screen.getByText('Noch keine Aktivitäten')).toBeInTheDocument();
  });

  it('Formular-Validierung: leerer Name → Fehler, Dialog bleibt offen', async () => {
    const user = userEvent.setup();
    render(<App />);

    const dialog = await openAddDialog(user);
    await user.click(within(dialog).getByRole('button', { name: 'Speichern' }));

    expect(dialogIsOpen()).toBe(true);
    expect(screen.getByText('Gib der Aktivität einen Namen.')).toBeInTheDocument();
    expect(screen.queryByText('Noch keine Aktivitäten')).not.toBeInTheDocument();
  });
});

describe('App: Tagesstatus & Persistenz', () => {
  it('Abhaken überlebt einen Reload (gleicher localStorage)', async () => {
    const user = userEvent.setup();
    const first = render(<App />);
    await addActivity(user, { name: 'E-Mails aufräumen' });

    await user.click(screen.getByRole('button', { name: '„E-Mails aufräumen“ abhaken' }));
    expect(screen.getByRole('button', { name: '„E-Mails aufräumen“ abhaken' })).toHaveAttribute(
      'aria-pressed',
      'true',
    );

    first.unmount();
    render(<App />);

    const check = screen.getByRole('button', {
      name: '„E-Mails aufräumen“ wieder offen machen',
    });
    expect(check).toHaveAttribute('aria-pressed', 'true');
  });

  it('Ziel 3: drei Klicks = erledigt, vierter Klick setzt zurück', async () => {
    const user = userEvent.setup();
    render(<App />);
    await addActivity(user, { name: 'Laufen', target: '3' });

    const check = () =>
      screen.getByRole('button', {
        name: /Fortschritt für „Laufen“/,
      });

    await user.click(check());
    expect(screen.getByText('1/3')).toBeInTheDocument();
    await user.click(check());
    await user.click(check());

    const doneButton = screen.getByRole('button', {
      name: '„Laufen“ ist erledigt – auf 0 zurücksetzen',
    });
    expect(doneButton).toHaveAttribute('aria-pressed', 'true');
    expect(screen.getByText('3/3')).toBeInTheDocument();

    await user.click(doneButton);
    expect(screen.getByText('0/3')).toBeInTheDocument();
  });

  it('Tastatur: Space auf dem Toggle-Button häkt ab', async () => {
    const user = userEvent.setup();
    render(<App />);
    await addActivity(user, { name: 'Atmen üben' });

    const check = screen.getByRole('button', { name: '„Atmen üben“ abhaken' });
    check.focus();
    await user.keyboard(' ');

    expect(
      screen.getByRole('button', { name: '„Atmen üben“ wieder offen machen' }),
    ).toHaveAttribute('aria-pressed', 'true');
  });
});

describe('App: Datumswechsel', () => {
  it('Status bleibt pro Tag erhalten, Navigation via Hash', async () => {
    const user = userEvent.setup();
    render(<App />);
    await addActivity(user, { name: 'Journal schreiben' });

    await user.click(screen.getByRole('button', { name: '„Journal schreiben“ abhaken' }));

    // weiter nach vorn (zukünftiger Tag)
    await user.click(screen.getByRole('button', { name: 'Nächster Tag' }));
    expect(window.location.hash).toBe('#/2026-09-28');
    expect(screen.getByRole('heading', { level: 1 })).toHaveTextContent(
      'Montag, 28. September',
    );
    expect(screen.getByText('künftiger Tag')).toBeInTheDocument();

    // künftiger Tag: Toggle gesperrt
    const futureCheck = screen.getByRole('button', { name: '„Journal schreiben“ abhaken' });
    expect(futureCheck).toBeDisabled();

    // zurück zu heute: Status ist erhalten
