import { createContext } from 'react';
import type { AppData, Recovery } from '../lib/types';
import type { Action } from './store';

export interface AppContextValue {
  data: AppData;
  /** Wie der gespeicherte Zustand beim Laden eingestuft wurde. */
  recovery: Recovery;
  dispatch: (action: Action) => void;
  dismissRecovery: () => void;
}

export const AppContext = createContext<AppContextValue | null>(null);

import { createContext } from 'react';

export type ToastTone = 'info' | 'error';

export interface ToastItem {
  id: number;
  message: string;
  tone: ToastTone;
}

export interface ToastContextValue {
  pushToast: (message: string, tone?: ToastTone) => void;
  toasts: ToastItem[];
  dismissToast: (id: number) => void;
}

export const ToastContext = createContext<ToastContextValue | null>(null);

import {
  useCallback,
  useContext,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react';
import {
  ToastContext,
  type ToastContextValue,
  type ToastItem,
  type ToastTone,
} from './toast-context';

const TOAST_TTL_MS = 6000;

export function ToastProvider({ children }: { children: ReactNode }) {
  const [toasts, setToasts] = useState<ToastItem[]>([]);
  const nextId = useRef(1);

  const dismissToast = useCallback((id: number) => {
    setToasts((current) => current.filter((t) => t.id !== id));
  }, []);

  const pushToast = useCallback(
    (message: string, tone: ToastTone = 'info') => {
      const id = nextId.current++;
      setToasts((current) => [...current.slice(-2), { id, message, tone }]);
      window.setTimeout(() => dismissToast(id), TOAST_TTL_MS);
    },
    [dismissToast],
  );

  const value = useMemo<ToastContextValue>(
    () => ({ pushToast, toasts, dismissToast }),
    [pushToast, toasts, dismissToast],
  );

  return <ToastContext.Provider value={value}>{children}</ToastContext.Provider>;
}

/** Screenreader-sichtbare, sichtbare Toast-Leiste. */
export function ToastViewport() {
  const ctx = useContext(ToastContext);
  if (!ctx) return null;
  const { toasts, dismissToast } = ctx;
  return (
    <div className="toasts" role="status" aria-live="polite">
      {toasts.map((toast) => (
        <div key={toast.id} className={`toast toast--${toast.tone}`}>
          <span className="toast__message">{toast.message}</span>
          <button
            type="button"
            className="toast__close"
            onClick={() => dismissToast(toast.id)}
            aria-label="Meldung schließen"
          >
            ✕
          </button>
        </div>
      ))}
    </div>
  );
}

import { useContext } from 'react';
import { ToastContext, type ToastContextValue } from './toast-context';

/** Zugriff auf die Toast-Api (push/dismiss). */
export function useToast(): ToastContextValue {
  const ctx = useContext(ToastContext);
  if (!ctx) throw new Error('useToast muss innerhalb von <ToastProvider> verwendet werden');
  return ctx;
}

import { useContext } from 'react';
import { AppContext, type AppContextValue } from './app-context';

/** Zugriff auf AppData, Recovery-Status und Dispatch. */
export function useApp(): AppContextValue {
  const ctx = useContext(AppContext);
  if (!ctx) throw new Error('useApp muss innerhalb von <AppProvider> verwendet werden');
  return ctx;
}

import {
  useEffect,
  useMemo,
  useReducer,
  useRef,
  useState,
  type ReactNode,
} from 'react';
import { load, save } from '../lib/storage';
import { reducer } from './store';
import { AppContext, type AppContextValue } from './app-context';
import { ToastProvider } from './Toasts';
import { useToast } from './useToast';

/**
 * Hält das AppData im Reducer, lädt einmalig aus localStorage und speichert bei
 * jeder Änderung zurück.
 *
 * Sonderfall „corrupt“: Nicht lesbare Daten werden beim ersten Rendern nicht
 * sofort überschrieben – der kaputte Zustand bleibt bestehen, bis der Nutzer
 * tatsächlich etwas ändert (damit das Banner bei jedem Reload ehrlich bleibt).
 */
export function AppProvider({ children }: { children: ReactNode }) {
  const loaded = useMemo(() => load(), []);
  const [data, dispatch] = useReducer(reducer, loaded.data);
  const [recovery, setRecovery] = useState(loaded.recovery);
  const { pushToast } = useToast();

  const firstRun = useRef(true);
  const startedCorrupt = useRef(loaded.recovery === 'corrupt');

  useEffect(() => {
    if (firstRun.current) {
      firstRun.current = false;
      if (startedCorrupt.current) return; // erst nach echten Änderungen überschreiben
    }
    if (!save(data)) {
      pushToast(
        'Änderung konnte nicht gespeichert werden – der Browser-Speicher ist voll oder gesperrt.',
      );
    }
  }, [data, pushToast]);

  useEffect(() => {
    if (startedCorrupt.current && !firstRun.current) {
      // Erste echte Änderung persistiert → kaputter Zustand wurde ersetzt.
      startedCorrupt.current = false;
      setRecovery('ok');
    }
  }, [data]);

  const value = useMemo<AppContextValue>(
    () => ({
      data,
      recovery,
      dispatch,
      dismissRecovery: () => setRecovery('ok'),
    }),
    [data, recovery],
  );

  return (
    <ToastProvider>
      <AppContext.Provider value={value}>{children}</AppContext.Provider>
    </ToastProvider>
  );
}

content.text:
`AppProvider` calls `useToast()` — but `AppProvider` itself is the component that wraps `ToastProvider` (children are inside the provider). Since the provider's body runs before the ToastContext.Provider in the tree, `useToast` throws an error. The Provider needs to be restructured: `AppProvider` should be split into an outer component (which renders ToastProvider + the inner one). The inner component uses useToast.

```tsx
export function AppProvider({ children }) {
  return (
    <ToastProvider>
      <AppDataProvider>{children}</AppDataProvider>
    </ToastProvider>
  );
}

function AppDataProvider({ children }) {
  ... use useToast ...
}
```
AppDataProvider is a non-exported component within the same file — no problem for react-refresh (only exports matter; non-exported function components are fine).

